const C={navy:[.052,.095,.14],page:[.068,.117,.166],slate:[.136,.216,.279],gold:[.78,.615,.41],light:[.965,.958,.936],ink:[.936,.926,.893],gray:[.668,.732,.774],rule:[.251,.322,.376],cream:[.101,.164,.221],lineDark:[.29,.37,.42],blue:[.765,.808,.834],white:[1,1,1]};
const fixed=n=>Number(n).toFixed(2).replace(/\.00$/,'');
const ascii=s=>String(s??'').normalize('NFKD').replace(/[\u0300-\u036f]/g,'').replace(/[\u2010-\u2015]/g,'-').replace(/[\u2018\u2019]/g,"'").replace(/[\u201c\u201d]/g,'"').replace(/[\u2190-\u21ff]/g,'>');
const lit=s=>'('+ascii(s).replace(/[\\()]/g,c=>'\\'+c).replace(/·/g,'\\267').replace(/[^\x20-\x7e\\]/g,'?')+')';
const rgb=k=>(C[k]||k).map(fixed).join(' ');
const color=(c,stroke=false)=>rgb(c)+(stroke?' RG\n':' rg\n');
const rect=(x,y,w,h,c)=>color(c)+`${fixed(x)} ${fixed(y)} ${fixed(w)} ${fixed(h)} re f\n`;
const line=(x,y,x2,y2,c='rule',lw=.7)=>color(c,true)+`${fixed(lw)} w ${fixed(x)} ${fixed(y)} m ${fixed(x2)} ${fixed(y2)} l S\n`;
const text=(x,y,s,size=11,font='F1',c='ink')=>`BT /${font} ${fixed(size)} Tf ${color(c)}1 0 0 1 ${fixed(x)} ${fixed(y)} Tm ${lit(s)} Tj ET\n`;
const pic=(id,x,y,w,h)=>`q ${fixed(w)} 0 0 ${fixed(h)} ${fixed(x)} ${fixed(y)} cm /${id} Do Q\n`;
// Only the ORIGINAL numeral 5 from /Logo, not the PADEL 5IVE wordmark.
// Clip the lower 18% of the source image, then rotate the number as a subtle, almost upright editorial watermark. Draw first, behind
// every score/standings/bracket page.
const emboss=()=>{const a=0, w=445,h=520,x=470,y=-80;
 return `q /GSwm gs\n0 53 ${fixed(W)} ${fixed(H-132)} re W n\n${fixed(w*Math.cos(a))} ${fixed(w*Math.sin(a))} ${fixed(-h*Math.sin(a))} ${fixed(h*Math.cos(a))} ${fixed(x)} ${fixed(y)} cm\n0 0.18 1 0.82 re W n /Logo Do Q\n`;};
const ell=(s,max=42)=>{s=ascii(s);return s.length>max?s.slice(0,max-3).trimEnd()+'...':s;};
const wrap=(s,n=44)=>{let out=[],cur='';for(let w of ascii(s).split(/\s+/)){if((cur+' '+w).trim().length>n){if(cur)out.push(cur);cur=w;}else cur+=(cur?' ':'')+w;}if(cur)out.push(cur);return out;};
const dayDate=value=>{const raw=String(value??'').trim();if(!raw||raw==='NOT SET')return 'NOT SET';
 const iso=/^(\d{4})-(\d{2})-(\d{2})$/.exec(raw);let dt;
 if(iso){dt=new Date(Date.UTC(+iso[1],+iso[2]-1,+iso[3]));if(dt.getUTCFullYear()!==+iso[1]||dt.getUTCMonth()+1!==+iso[2]||dt.getUTCDate()!==+iso[3])return raw;}
 else {dt=new Date(raw);if(!Number.isFinite(dt.getTime()))return raw;}
 return new Intl.DateTimeFormat('en-GB',{weekday:'long',day:'2-digit',month:'long',year:'numeric',timeZone:'UTC'}).format(dt).replace(/^([^,]+),\s*/,'$1 · ');
};

class PDF{
 constructor(){this.pages=[];}
 add(content){this.pages.push(content);}
 bytes(){let obj=[null];const add=x=>(obj.push(x),obj.length-1);
  const font1=add('<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>');
  const font2=add('<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold /Encoding /WinAnsiEncoding >>');
  const font3=add('<< /Type /Font /Subtype /Type1 /BaseFont /Times-Italic /Encoding /WinAnsiEncoding >>');
  const font4=add('<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Oblique /Encoding /WinAnsiEncoding >>');
  const watermark=add('<< /Type /ExtGState /ca 0.033 /CA 0.033 >>');
  const stream=(dict,body)=>add(`<< ${dict} /Length ${body.length} >>\nstream\n${body}\nendstream`);
  // PDF soft mask retains the original master's transparent logo, not a faux font glyph.
  const sm=stream(`/Type /XObject /Subtype /Image /Width ${IMAGES.logo.width} /Height ${IMAGES.logo.height} /ColorSpace /DeviceGray /BitsPerComponent 8 /Filter [/ASCII85Decode /FlateDecode]`,IMAGES.logo.alpha);
  const logo=stream(`/Type /XObject /Subtype /Image /Width ${IMAGES.logo.width} /Height ${IMAGES.logo.height} /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter [/ASCII85Decode /FlateDecode] /SMask ${sm} 0 R`,IMAGES.logo.rgb);
  const image=(img)=>stream(`/Type /XObject /Subtype /Image /Width ${img.width} /Height ${img.height} /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter [/ASCII85Decode /DCTDecode]`,img.stream);
  const cover=image(IMAGES.cover),champ=image(IMAGES.champ);
  const pagesId=add('');const ids=[];
  for(const p of this.pages){const contents=stream('',p);ids.push(add(`<< /Type /Page /Parent ${pagesId} 0 R /MediaBox [0 0 ${W} ${H}] /Resources << /Font << /F1 ${font1} 0 R /F2 ${font2} 0 R /F3 ${font3} 0 R /F4 ${font4} 0 R >> /XObject << /Logo ${logo} 0 R /Venue ${cover} 0 R /Champion ${champ} 0 R >> /ExtGState << /GSwm ${watermark} 0 R >> >> /Contents ${contents} 0 R >>`));}
  obj[pagesId]=`<< /Type /Pages /Count ${ids.length} /Kids [${ids.map(id=>id+' 0 R').join(' ')}] >>`;
  const root=add(`<< /Type /Catalog /Pages ${pagesId} 0 R >>`);
  let out='%PDF-1.4\n%PADEL5IVE\n';const offsets=[0];for(let i=1;i<obj.length;i++){offsets.push(out.length);out+=`${i} 0 obj\n${obj[i]}\nendobj\n`;}
  const xref=out.length;out+=`xref\n0 ${obj.length}\n0000000000 65535 f \n`;for(const off of offsets.slice(1))out+=String(off).padStart(10,'0')+' 00000 n \n';out+=`trailer\n<< /Size ${obj.length} /Root ${root} 0 R >>\nstartxref\n${xref}\n%%EOF\n`;
  return new Blob([new TextEncoder().encode(out)],{type:'application/pdf'});
 }
}
