function koDiagram(ko,group,page){
 const matches=ko.filter(k=>k.group===group).slice();if(!matches.length)return null;
 // Canonical feeders, never infer a connection if the qualified team cannot be verified.
 const defs={9:['L1','L2'],10:['L3','L4'],11:['L5','L6'],12:['L7','L8'],13:['W1','W2'],14:['W3','W4'],15:['W5','W6'],16:['W7','W8'],17:['W9','L16'],18:['W10','L15'],19:['W11','L14'],20:['W12','L13'],21:['W13','W14'],22:['W15','W16'],23:['W17','W18'],24:['W19','W20'],25:['W21','W22'],26:['W23','L22'],27:['W24','L21'],28:['W26','W27'],29:['W28','L25'],30:['W25','W29'],31:['W30','L30']};
 const canonical=id=>group==='W'?(id<=8?1:id<=16?2:id<=22?3:4):(id<=12?1:id<=20?2:id<=24?3:id<=27?4:id===28?5:6);
 const all=new Map(matches.map(m=>[Number(m.id),m]));
 const roundOf=m=>Number(m.round)>0?Number(m.round):canonical(Number(m.id));
 const rounds=[...new Set(matches.map(roundOf))].sort((a,b)=>a-b);
 const cols=rounds.map(round=>({round,items:matches.filter(m=>roundOf(m)===round).sort((a,b)=>Number(a.id)-Number(b.id))}));
 const cw=Math.min(204,Math.floor((W-104-Math.max(0,cols.length-1)*26)/cols.length));
 const gap=cols.length>1?(W-104-cols.length*cw)/(cols.length-1):0;
 const cardH=32, pitch=39, firstN=Math.max(...cols.map(c=>c.items.length));
 const top=Math.min(H-248,Math.max(340,86+(firstN-1)*pitch));
 const loc=new Map();let p=masthead(group==='W'?'Connected Winners Bracket':'Connected Losers Bracket',page);
 p+=text(49,H-111,'STAGE 2  /  '+(group==='W'?'WINNERS BRACKET':'LOSERS BRACKET'),10,'F2','gold');
 p+=text(49,H-153,group==='W'?'The Road to the Final':'The Second Chance',29,'F2','ink');
 p+=text(49,H-181,'FOLLOW THE CONNECTORS  ·  ROUND PROGRESSION LEFT TO RIGHT',9,'F1','gray');
 const key=ids=>(ids||[]).slice().sort((a,b)=>a-b).join('|');
 const winner=m=>Number(m.score?.[0])>Number(m.score?.[1])?m.teamA:m.teamB;
 function parents(m){let ids=(defs[m.id]||[]).filter(x=>x[0]===group).map(x=>Number(x.slice(1))).filter(id=>loc.has(id));
  if(ids.length)return [...new Set(ids)];
  const sought=new Set([key(m.teamA),key(m.teamB)]);
  // Prefer winners from immediate previous columns; avoid unrelated repeat-opponent links.
  const n=roundOf(m),prev=matches.filter(k=>roundOf(k)<n&&sought.has(key(winner(k))));
  const maxRound=Math.max(0,...prev.map(roundOf));
  return prev.filter(k=>roundOf(k)===maxRound&&loc.has(Number(k.id))).map(k=>Number(k.id));
 }
 cols.forEach((col,ci)=>{
   const x=52+ci*(cw+gap);p+=text(x,H-206,`ROUND ${String(col.round).padStart(2,'0')}`,9,'F2','gold');
   p+=text(x,H-223,`${col.items.length} CONFIRMED MATCH${col.items.length===1?'':'ES'}`,7.6,'F1','gray');
   p+=line(x,H-231,x+cw,H-231,'rule',.8);
   for(let j=0;j<col.items.length;j++){
     const m=col.items[j],prev=parents(m).map(id=>loc.get(id)).filter(Boolean);
     let y=(ci&&prev.length)?prev.reduce((a,b)=>a+b.y,0)/prev.length:top-j*(col.items.length>6?35:Math.min(78,Math.max(44,260/Math.max(1,col.items.length-1))));
     if(j){const last=loc.get(Number(col.items[j-1].id));if(last)y=Math.min(y,last.y-pitch);}
     // More vertical breathing room for stages with fewer matches.
     y=Math.max(74,Math.min(top,y));
     loc.set(Number(m.id),{x,y});
   }
 });
 // Connector path drawn behind match cards and only when both matches exist.
 for(const m of matches){const dest=loc.get(Number(m.id));if(!dest)continue;const ids=parents(m);
  for(const id of ids){const a=loc.get(id);if(!a||a.x>=dest.x)continue;
   const x0=a.x+cw, y0=a.y+cardH/2, x1=dest.x,y1=dest.y+cardH/2,mid=(x0+x1)/2;
   p+=line(x0,y0,mid,y0,'gray',.85)+line(mid,y0,mid,y1,'gold',.9)+line(mid,y1,x1,y1,'gray',.85);
  }
 }
 for(const col of cols)for(const m of col.items){const pos=loc.get(Number(m.id)),winA=Number(m.score[0])>Number(m.score[1]);
  const maxLen=Math.max(7,Math.floor((cw-53)/4.2));
  p+=rect(pos.x,pos.y,cw,cardH,'cream');
  p+=line(pos.x,pos.y,pos.x,pos.y+cardH,'gold',2.5)+line(pos.x,pos.y+cardH,pos.x+cw,pos.y+cardH,'rule',.7);
  p+=text(pos.x+7,pos.y+19,`${group}${m.id}`,7,'F2','gold');
  p+=text(pos.x+31,pos.y+19,ell(m.teamAText,maxLen),7.4,winA?'F2':'F1',winA?'ink':'gray');
  p+=text(pos.x+31,pos.y+6,ell(m.teamBText,maxLen),7.4,winA?'F1':'F2',winA?'gray':'ink');
  p+=text(pos.x+cw-15,pos.y+19,m.score[0],9,'F2',winA?'gold':'gray');
  p+=text(pos.x+cw-15,pos.y+6,m.score[1],9,'F2',winA?'gray':'gold');
  p+=line(pos.x,pos.y,pos.x+cw,pos.y,'rule',.55);
 }
 p+=text(52,63,cols.length>4?'COMPACT BRACKET · FULL TEAM NAMES IN MATCH LEDGER':'CONNECTED MATCH PATH · WINNING PAIR HIGHLIGHTED IN CHAMPAGNE',8,'F1','gray');return p;
}
